head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > getFirstChildElements]<br/>XML Element 의 모든 자식 Element 노드를 배열로 반환합니다.",
    "validation" : [
        "element(필수) 파라미터로 자식을 검색할 XML Element 노드를 설정할 수 있어야 합니다.",
        "모든 자식 Element 노드의 배열을 반환해야 합니다.",
        "직계 자식 Element 만 수집해야 합니다.",
        "텍스트 노드나 CDATA 노드는 포함하지 않아야 합니다.",
        "Element 타입의 자식 노드가 없으면 빈 배열([])을 반환해야 합니다.",
    ]
}

scwin.testDoc = null;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.testDoc = WebSquare.xml.parse(
        "<root>" +
            "<parent1><title>Harry Potter</title><price>29.99</price><author>J.K. Rowling</author></parent1>" +
            "<parent2>text only</parent2>" +
            "<parent3></parent3>" +
            "<parent4><![CDATA" + "[some data]]" + "><item>First</item><item>Second</item></parent4>" +
            "<parent5><outer><inner>nested</inner></outer></parent5>" +
        "</root>"
    );
};



scwin.btn_getFirstChildElements_onclick = function () {
    var elementName = par_element.getValue();

    var targetNode = WebSquare.xml.findNode(scwin.testDoc, "root/" + elementName);
    var result = WebSquare.xml.getFirstChildElements(targetNode);

    wf_body_bottom.getObj("scwin").setReturnValue("getFirstChildElements(" + elementName + ")");
    wf_body_bottom.getObj("scwin").setReturnValue("배열 길이 : " + result.length);

    if (result.length > 0) {
        for (var i = 0; i < result.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("[" + i + "] nodeName : " + result[i].nodeName + " / 내용 : " + WebSquare.xml.serialize(result[i]));
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("결과 : [] (빈 배열)");
    }
}
